import json,re
p=json.load(open('input/packet.json'))
rx=re.compile('合并|追溯|重述|会计政策|会计估计|可比|不可比|同口径|restat|consolidat|adjust',re.I)
def walk(v,path=''):
 if isinstance(v,dict):
  for k,w in v.items(): walk(w,path+'/'+k.replace('~','~0').replace('/','~1'))
 elif isinstance(v,list):
  for i,w in enumerate(v): walk(w,path+'/'+str(i))
 elif rx.search(path) or (isinstance(v,str) and rx.search(v)):
  if isinstance(v,str) and len(v)>1200:
   snippets=[v[max(0,m.start()-65):min(len(v),m.end()+140)] for m in rx.finditer(v)]
   print(path, json.dumps({'matched_excerpts':snippets},ensure_ascii=False))
  else: print(path,json.dumps(v,ensure_ascii=False))
walk(p)
print('\\n/facts/own/announcement')
print(json.dumps(p['facts']['own']['announcement'],ensure_ascii=False,indent=2))
PY"

